:root {
  --bg: #07080a;
  --bg-2: #0b0d11;
  --panel: #11151b;
  --panel-2: #161b22;
  --panel-3: #1b2129;
  --line: #272d36;
  --line-2: #3a4250;
  --text: #f1ece2;
  --muted: #9aa2ae;
  --dim: #6c7480;
  --red: #e84545;
  --red-2: #ff6262;
  --red-deep: #8e2027;
  --gold: #f0c75e;
  --gold-2: #ffe08a;
  --teal: #68d6c2;
  --green: #72d39a;
  --purple: #b08ce8;
  --orange: #e89a4b;
  --font-display: "Arial Black", "Helvetica Neue", Impact, "Arial Bold", sans-serif;
  --font-body: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", Consolas, "Liberation Mono", Menlo, monospace;
  --shadow: 0 24px 60px -30px rgba(0, 0, 0, .9);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100dvh;
  background:
    radial-gradient(1100px 620px at 84% -10%, rgba(232, 69, 69, .13), transparent 62%),
    radial-gradient(900px 700px at -12% 105%, rgba(240, 199, 94, .055), transparent 58%),
    var(--bg);
  color: var(--text);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, .018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .018) 1px, transparent 1px);
  background-size: 46px 46px;
  mask-image: radial-gradient(1000px 700px at 55% 20%, #000 20%, transparent 85%);
}
::selection { background: var(--red); color: #fff; }
h1, h2, h3, p { margin: 0; }
button { font: inherit; }
img, svg { display: block; }
a { color: inherit; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: #0a0c0f; }
::-webkit-scrollbar-thumb { background: #2c333d; border: 2px solid #0a0c0f; border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: #3a4350; }

.is-hidden { display: none !important; }
.icon { flex: 0 0 auto; }
.live-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--red); box-shadow: 0 0 0 0 rgba(232, 69, 69, .55);
  animation: livePulse 2s infinite;
  display: inline-block;
}
@keyframes livePulse {
  0% { box-shadow: 0 0 0 0 rgba(232, 69, 69, .5); }
  70% { box-shadow: 0 0 0 7px rgba(232, 69, 69, 0); }
  100% { box-shadow: 0 0 0 0 rgba(232, 69, 69, 0); }
}

.eyebrow {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--red-2);
}
.eyebrow--gold { color: var(--gold); }
.panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, .022), transparent 38%), var(--panel);
  border: 1px solid var(--line);
  border-radius: 3px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .025), var(--shadow);
}
.panel-head {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin-bottom: 14px; color: var(--dim);
}

/* ------------------------------------------------------------------ buttons */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 16px;
  border: 1px solid var(--line-2);
  border-radius: 2px;
  background: #181d25;
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: .075em;
  line-height: 1.15;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
  transition: background .16s ease, border-color .16s ease, transform .16s ease, filter .16s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
}
.btn:hover { background: #20262f; border-color: #4a5361; transform: translateY(-1px); }
.btn:active { transform: translateY(0); }
.btn:focus-visible, .icon-btn:focus-visible, .nav-item:focus-visible, .heist-action:focus-visible,
.partner-option:focus-visible, .quick-action:focus-visible, .mnav-btn:focus-visible, .help-link:focus-visible {
  outline: 2px solid var(--gold); outline-offset: 2px;
}
.btn-primary {
  background: linear-gradient(180deg, #f05757, #ce333a);
  border-color: #ff7b7b;
  color: #fff;
  box-shadow: 0 10px 28px -14px rgba(232, 69, 69, .85);
}
.btn-primary:hover { background: linear-gradient(180deg, #ff6666, #dc3a41); filter: saturate(1.06); }
.btn-gold {
  background: linear-gradient(180deg, #f3cf6e, #d9a83d);
  border-color: #ffe39b;
  color: #1a1408;
  box-shadow: 0 10px 28px -16px rgba(240, 199, 94, .8);
}
.btn-gold:hover { background: linear-gradient(180deg, #ffe08a, #e5b54c); }
.btn-ghost { background: rgba(255, 255, 255, .018); color: var(--muted); }
.btn-ghost:hover { color: var(--text); }
.btn-danger { border-color: #84343a; color: #ff9a9a; background: rgba(232, 69, 69, .08); }
.btn-danger:hover { background: rgba(232, 69, 69, .16); border-color: #b54a52; }
.btn-sm { padding: 8px 11px; font-size: 9.5px; }
.btn-block { width: 100%; }
.btn.is-disabled, .btn.is-maxed, .btn.is-unaffordable { opacity: .55; }
.btn.is-maxed { opacity: .7; color: var(--green); border-color: #2f4b3a; }
.btn:disabled { opacity: .42; cursor: not-allowed; transform: none; }

.icon-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: var(--panel);
  color: var(--muted);
  cursor: pointer;
  transition: .16s ease;
}
.icon-btn:hover { color: var(--text); border-color: var(--line-2); background: var(--panel-2); }

/* ------------------------------------------------------------------ intro */
.intro {
  position: fixed; inset: 0; z-index: 100;
  display: grid; place-items: center;
  padding: 30px;
  overflow: auto;
  background:
    radial-gradient(900px 620px at 76% 18%, rgba(232, 69, 69, .14), transparent 62%),
    radial-gradient(800px 500px at 14% 90%, rgba(240, 199, 94, .05), transparent 60%),
    #060708;
}
.intro.is-hidden { display: none; }
.intro-grid {
  position: absolute; inset: 0; pointer-events: none;
  background-image:
    linear-gradient(rgba(255, 255, 255, .022) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, .022) 1px, transparent 1px);
  background-size: 54px 54px;
  mask-image: radial-gradient(900px 640px at 50% 44%, #000 10%, transparent 88%);
}
.intro-beam {
  position: absolute; inset: -20%;
  background: conic-gradient(from 210deg at 74% 16%, transparent 0deg, rgba(232, 69, 69, .12) 30deg, transparent 70deg);
  filter: blur(40px);
  pointer-events: none;
}
.intro-shell { width: min(1120px, 100%); position: relative; z-index: 1; }
.intro-card {
  position: relative;
  display: grid;
  grid-template-columns: 1.17fr .83fr;
  min-height: 580px;
  border: 1px solid #303640;
  background: linear-gradient(145deg, rgba(23, 27, 34, .96), rgba(9, 11, 14, .98) 68%);
  box-shadow: 0 50px 100px -34px rgba(0, 0, 0, .95), inset 0 1px 0 rgba(255, 255, 255, .05);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 26px), calc(100% - 26px) 100%, 0 100%);
}
.intro-card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px;
  background: linear-gradient(90deg, transparent, var(--red) 25%, var(--red-2) 55%, transparent);
  opacity: .9;
}
.intro-copy { padding: 44px 46px 38px; display: flex; flex-direction: column; justify-content: center; }
.intro-kicker {
  display: flex; align-items: center; gap: 9px;
  font-family: var(--font-mono); font-size: 9.5px; font-weight: 700;
  letter-spacing: .18em; color: var(--red-2); text-transform: uppercase;
}
.intro-logo { display: flex; align-items: center; gap: 22px; margin: 24px 0 12px; }
.logo-mark {
  width: 76px; height: 76px; flex: 0 0 auto;
  display: grid; place-items: center;
  border: 2px solid var(--red);
  background: radial-gradient(circle at 50% 38%, rgba(232, 69, 69, .2), #0a0c0f 70%);
  font-family: var(--font-display);
  font-size: 50px; line-height: 1; color: var(--red-2);
  box-shadow: 0 0 42px -8px rgba(232, 69, 69, .45), inset 0 0 24px rgba(232, 69, 69, .1);
  transform: rotate(-2deg);
}
.logo-team {
  display: block; font-family: var(--font-mono); font-size: 10px; font-weight: 700;
  letter-spacing: .44em; color: var(--muted); margin-bottom: 2px;
}
.intro-logo h1 {
  font-family: var(--font-display);
  font-size: clamp(52px, 6.1vw, 88px);
  line-height: .82;
  letter-spacing: -.035em;
  color: var(--text);
  text-shadow: 4px 4px 0 rgba(232, 69, 69, .22);
}
.intro-tag {
  font-family: var(--font-mono);
  font-size: 11px; letter-spacing: .13em; text-transform: uppercase;
  color: var(--gold); margin: 10px 0 22px;
}
.intro-story { border-left: 2px solid #3a3034; padding-left: 18px; display: grid; gap: 10px; }
.intro-story p { color: var(--muted); font-size: 14.5px; line-height: 1.6; max-width: 470px; }
.intro-story strong { color: var(--text); }
.intro-steps {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px;
  margin: 24px 0 26px; max-width: 480px;
}
.intro-steps span {
  display: flex; align-items: center; gap: 9px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, .018);
  padding: 9px 11px; font-family: var(--font-mono); font-size: 9px;
  letter-spacing: .06em; text-transform: uppercase; color: var(--muted);
}
.intro-steps b { color: var(--red-2); font-size: 10px; }
.intro-actions { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.btn-start { min-width: 200px; height: 54px; font-size: 13px; letter-spacing: .16em; }
.intro-save {
  display: flex; align-items: center; flex-wrap: wrap; gap: 7px;
  font-family: var(--font-mono); font-size: 9.5px; color: var(--dim);
}
.intro-save strong { color: var(--muted); font-weight: 700; }
.intro-save em { font-style: normal; color: #56606c; }
.save-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); }
.save-dot.is-new { background: var(--red); }
.intro-fine { margin-top: 16px; font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .08em; color: #505863; text-transform: uppercase; }
.intro-art {
  position: relative; overflow: hidden;
  border-left: 1px solid var(--line);
  background:
    radial-gradient(circle at 52% 42%, rgba(232, 69, 69, .17), transparent 48%),
    linear-gradient(180deg, #0d1015, #07080a);
}
.intro-art::before {
  content: ""; position: absolute; inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, .03) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, .03) 1px, transparent 1px);
  background-size: 38px 38px;
  mask-image: radial-gradient(circle at 50% 45%, #000, transparent 75%);
}
.intro-art-glow {
  position: absolute; inset: 15% 10% 28%;
  background: radial-gradient(circle, rgba(232, 69, 69, .24), transparent 62%);
  filter: blur(20px);
}
.intro-art-r { position: absolute; inset: 0; display: grid; place-items: center; }
.r-ring {
  position: absolute; width: 300px; height: 300px; border-radius: 50%;
  border: 1px solid rgba(232, 69, 69, .28);
}
.r-ring--1 { animation: ringSpin 26s linear infinite; border-style: dashed; }
.r-ring--2 { width: 380px; height: 380px; border-color: rgba(232, 69, 69, .11); }
.r-ring--1::before, .r-ring--2::before {
  content: ""; position: absolute; top: -4px; left: 50%; width: 7px; height: 7px;
  background: var(--red); border-radius: 50%; box-shadow: 0 0 14px var(--red);
}
.r-letter {
  font-family: var(--font-display);
  font-size: 190px; line-height: 1; color: var(--red);
  text-shadow: 0 0 70px rgba(232, 69, 69, .4), 8px 8px 0 rgba(0, 0, 0, .35);
  transform: rotate(-4deg);
  animation: rFloat 7s ease-in-out infinite;
}
.r-tag {
  position: absolute; bottom: 27%; right: 24%;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: .2em; color: var(--red-2);
  border: 1px solid var(--red-deep); padding: 5px 8px; background: #0a0c0f;
}
@keyframes ringSpin { to { transform: rotate(360deg); } }
@keyframes rFloat { 0%, 100% { transform: rotate(-4deg) translateY(0); } 50% { transform: rotate(-3deg) translateY(-10px); } }
.intro-art-city {
  position: absolute; left: 0; right: 0; bottom: 0; height: 36%;
  display: flex; align-items: flex-end; gap: 4px; padding: 0 9%;
  opacity: .85;
}
.intro-art-city span {
  flex: 0 0 var(--w); height: var(--h);
  background: linear-gradient(180deg, #14181f, #090b0e);
  border-top: 1px solid #2a3039;
  box-shadow: inset 0 10px 18px -10px rgba(232, 69, 69, .25);
}
.intro-art-label {
  position: absolute; left: 24px; bottom: 22px;
  font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .18em; line-height: 1.6;
  color: var(--dim); text-transform: uppercase;
}
.intro-art-label em { font-style: normal; color: var(--red-2); }
.intro-foot {
  display: flex; justify-content: space-between; gap: 16px;
  margin-top: 14px; padding: 0 4px;
  font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .13em;
  color: #4e5661; text-transform: uppercase;
}

/* ------------------------------------------------------------------ topbar */
.app { min-height: 100dvh; }
.topbar {
  position: sticky; top: 0; z-index: 40;
  display: flex; align-items: center; gap: 24px;
  height: 64px; padding: 0 24px;
  border-bottom: 1px solid var(--line);
  background: rgba(8, 9, 11, .9);
  backdrop-filter: blur(18px);
}
.brand-wrap { flex: 0 0 auto; min-width: 248px; }
.brand {
  display: flex; align-items: baseline; gap: 8px;
  font-family: var(--font-display);
  font-size: 15px; letter-spacing: .035em; line-height: 1;
  white-space: nowrap;
}
.brand-r {
  width: 24px; height: 24px; display: grid; place-items: center;
  border: 1px solid var(--red); color: var(--red-2);
  font-size: 17px; line-height: 1; background: rgba(232, 69, 69, .08);
  transform: rotate(-2deg);
}
.brand-team { color: var(--muted); font-size: 11px; letter-spacing: .16em; }
.brand em { color: var(--red); font-style: normal; }
.brand strong { color: var(--text); letter-spacing: .04em; }
.brand-sub {
  margin-top: 4px; padding-left: 32px;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .17em;
  color: var(--dim); text-transform: uppercase;
}
.topres { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
.res {
  display: flex; align-items: center; gap: 7px;
  min-width: 0; padding: 7px 11px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, .018);
  color: var(--muted); border-radius: 2px;
  font-family: var(--font-mono);
}
.res .icon { color: var(--dim); }
.res-label { font-size: 8px; letter-spacing: .14em; color: var(--dim); }
.res strong { color: var(--text); font-size: 11px; letter-spacing: .02em; white-space: nowrap; }
.res--credits .icon { color: var(--gold); }
.res--rep .icon { color: var(--gold); }
.res--heat .icon { color: var(--red-2); }
.res--balls .icon { color: var(--muted); }
.res--heat.is-hot { border-color: #5a2c2e; background: rgba(232, 69, 69, .09); }
.res--heat.is-critical { border-color: #7a2d31; background: rgba(232, 69, 69, .15); animation: heatPulse 1.8s infinite; }
.res--heat.is-hot strong, .res--heat.is-critical strong { color: #ff9a9a; }
@keyframes heatPulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(232, 69, 69, .3); } 50% { box-shadow: 0 0 18px -4px rgba(232, 69, 69, .55); } }
.topactions { display: flex; gap: 8px; flex: 0 0 auto; }

/* ------------------------------------------------------------------ shell */
.shell {
  display: grid;
  grid-template-columns: 262px minmax(0, 1fr);
  width: 100%; max-width: 1480px; margin: 0 auto;
}
.sidebar {
  position: sticky; top: 64px;
  height: calc(100dvh - 64px);
  overflow-y: auto;
  padding: 18px 15px 28px;
  border-right: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, .012), transparent 40%);
}
.view {
  min-width: 0;
  padding: 28px 30px 70px;
}

/* rank card */
.rank-card {
  position: relative;
  padding: 16px 15px 14px;
  border: 1px solid var(--line);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .028), transparent 45%),
    repeating-linear-gradient(-45deg, transparent 0 12px, rgba(255, 255, 255, .012) 12px 13px),
    var(--panel);
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
}
.rank-card::before {
  content: ""; position: absolute; top: 0; left: 0; width: 3px; height: 52px;
  background: var(--rank-color, var(--red));
  box-shadow: 0 0 18px var(--rank-color, var(--red));
}
.rank-card .rank-emblem {
  position: absolute; top: 13px; right: 13px;
  width: 58px; height: 58px; border-radius: 50%;
  border: 1px solid var(--rank-color, var(--red));
  background: radial-gradient(circle at 50% 40%, rgba(255, 255, 255, .09), rgba(0, 0, 0, .25));
  display: grid; place-items: center;
  box-shadow: 0 0 24px -10px var(--rank-color, var(--red));
}
.rank-r { font-family: var(--font-display); font-size: 28px; color: var(--rank-color, var(--red)); line-height: 1; }
.rank-stars {
  position: absolute; top: -8px; left: 50%; transform: translateX(-50%);
  font-size: 6px; letter-spacing: 1px; color: var(--gold); white-space: nowrap;
}
.rank-index {
  position: absolute; bottom: -5px; right: -3px;
  min-width: 21px; height: 15px; padding: 0 4px;
  display: grid; place-items: center;
  background: #0a0c0f; border: 1px solid var(--line-2);
  font-family: var(--font-mono); font-size: 7.5px; color: var(--muted);
}
.rank-copy { padding-right: 62px; }
.rank-copy h2 {
  font-family: var(--font-display);
  font-size: 24px; line-height: 1; letter-spacing: -.01em; text-transform: uppercase;
  margin: 4px 0 5px;
}
.rank-copy p { font-size: 10.5px; line-height: 1.4; color: var(--dim); min-height: 28px; }
.rank-progress { margin-top: 13px; }
.rank-progress-top {
  display: flex; justify-content: space-between; gap: 8px; margin-bottom: 6px;
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .08em;
  text-transform: uppercase; color: var(--dim);
}
.rank-progress-top span:last-child { color: var(--muted); }
.meter { display: block; height: 6px; background: #1d222a; border: 1px solid #2b313a; position: relative; overflow: hidden; }
.meter-fill { display: block; height: 100%; background: linear-gradient(90deg, #9c2b32, var(--red)); transition: width .5s ease; }
.meter--rank .meter-fill { background: linear-gradient(90deg, #8d6a25, var(--gold)); }
.meter--heat { height: 8px; }
.meter--heat .meter-fill { background: linear-gradient(90deg, #3e8d65, #d4b23f 45%, var(--red)); }
.meter--capacity .meter-fill { background: linear-gradient(90deg, #2f6f8c, var(--teal)); }
.btn-promote {
  width: 100%; margin-top: 12px; padding: 9px 10px;
  background: linear-gradient(180deg, #f3cf6e, #d6a63d);
  border-color: #ffe09a; color: #171207;
  animation: promoGlow 2.4s infinite;
}
@keyframes promoGlow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(240, 199, 94, .22); }
  50% { box-shadow: 0 0 22px -6px rgba(240, 199, 94, .55); }
}
.rank-next {
  margin-top: 9px; font-family: var(--font-mono); font-size: 8px; letter-spacing: .08em;
  color: var(--dim); text-transform: uppercase;
}
.rank-next--boss { color: var(--gold); }

/* side nav */
.side-nav { display: grid; gap: 4px; margin: 16px 0; }
.nav-item {
  display: flex; align-items: center; gap: 11px;
  width: 100%; padding: 10px 11px;
  border: 1px solid transparent; border-left: 2px solid transparent;
  background: transparent; color: var(--dim); text-align: left; cursor: pointer;
  transition: .16s ease;
}
.nav-item:hover { color: var(--muted); background: rgba(255, 255, 255, .025); }
.nav-item.is-active {
  color: var(--text); background: linear-gradient(90deg, rgba(232, 69, 69, .12), transparent 80%);
  border-left-color: var(--red); border-image: none;
}
.nav-item.is-active .icon { color: var(--red-2); }
.nav-copy { display: grid; gap: 1px; min-width: 0; }
.nav-copy strong {
  font-family: var(--font-mono); font-size: 10px; font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase;
}
.nav-copy em {
  font-style: normal; font-family: var(--font-mono); font-size: 7.5px;
  letter-spacing: .05em; color: var(--dim); text-transform: uppercase;
}
.nav-dot { margin-left: auto; width: 6px; height: 6px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 10px var(--gold); }

.partner-mini {
  display: flex; align-items: center; gap: 10px; width: 100%;
  margin-top: 6px; padding: 10px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, .015);
  color: var(--muted); text-align: left; cursor: pointer;
  transition: .16s ease;
}
.partner-mini:hover { border-color: var(--line-2); background: var(--panel); }
.partner-mini-sprite {
  width: 54px; height: 54px; flex: 0 0 auto;
  display: grid; place-items: center;
  background: radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--tc) 24%, transparent), transparent 70%), #0d1014;
  border: 1px solid color-mix(in srgb, var(--tc) 35%, var(--line));
}
.partner-mini-sprite .poke-sprite { width: 54px; height: 54px; }
.partner-mini-copy { display: grid; gap: 1px; min-width: 0; }
.partner-mini-copy em { font-style: normal; font-family: var(--font-mono); font-size: 7px; letter-spacing: .12em; color: var(--red-2); }
.partner-mini-copy strong { font-size: 13px; color: var(--text); }
.partner-mini-copy span { font-family: var(--font-mono); font-size: 7.5px; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.partner-mini .icon { margin-left: auto; color: var(--dim); }

.side-note {
  display: grid; gap: 3px; margin-top: 16px; padding: 12px 3px;
  border-top: 1px solid var(--line);
}
.side-note strong { font-size: 11.5px; color: var(--muted); }
.side-note span:last-child { font-family: var(--font-mono); font-size: 8px; color: var(--dim); line-height: 1.5; }
.help-link {
  display: flex; align-items: center; gap: 7px; width: 100%;
  margin-top: 4px; padding: 8px 3px;
  border: 0; background: transparent; color: var(--dim);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .1em;
  text-transform: uppercase; cursor: pointer;
}
.help-link:hover { color: var(--text); }

/* mobile nav */
.mobile-nav {
  display: none;
  position: fixed; left: 0; right: 0; bottom: 0; z-index: 45;
  grid-template-columns: repeat(3, 1fr);
  padding: 5px 8px calc(5px + env(safe-area-inset-bottom));
  background: rgba(8, 9, 11, .95);
  border-top: 1px solid var(--line);
  backdrop-filter: blur(18px);
}
.mnav-btn {
  position: relative;
  display: grid; place-items: center; gap: 2px;
  padding: 6px 4px 5px; border: 0; background: transparent;
  color: var(--dim); cursor: pointer;
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .12em;
}
.mnav-btn.is-active { color: var(--red-2); }
.mnav-btn.is-active .icon { filter: drop-shadow(0 0 6px rgba(232, 69, 69, .45)); }
.mnav-btn.is-locked { opacity: .55; }
.mobile-promo {
  position: absolute; top: 4px; right: calc(50% - 18px);
  width: 6px; height: 6px; border-radius: 50%; background: var(--gold);
  box-shadow: 0 0 8px var(--gold); display: none;
}
.mobile-promo.is-on { display: block; }

/* ------------------------------------------------------------------ toast */
.toast-root {
  position: fixed; right: 22px; bottom: 22px; z-index: 220;
  display: flex; flex-direction: column; gap: 8px; align-items: flex-end;
  pointer-events: none;
}
.toast {
  display: flex; align-items: flex-start; gap: 9px;
  max-width: 330px; padding: 11px 14px;
  border: 1px solid var(--line-2); border-left: 2px solid var(--red);
  background: rgba(18, 22, 28, .97);
  color: var(--text); box-shadow: 0 18px 40px -20px #000;
  font-family: var(--font-mono); font-size: 10px; line-height: 1.5;
  opacity: 0; transform: translateY(8px); transition: .22s ease;
}
.toast.is-in { opacity: 1; transform: translateY(0); }
.toast-mark { width: 6px; height: 6px; margin-top: 4px; border-radius: 50%; background: var(--red); flex: 0 0 auto; }
.toast--good { border-left-color: var(--green); }
.toast--good .toast-mark { background: var(--green); }
.toast--gold { border-left-color: var(--gold); }
.toast--gold .toast-mark { background: var(--gold); }
.toast--warn { border-left-color: var(--orange); }
.toast--warn .toast-mark { background: var(--orange); }
.toast-text { min-width: 0; }

/* shared view headings */
.view-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 24px;
  margin-bottom: 22px;
}
.view-head h1 {
  font-family: var(--font-display);
  font-size: clamp(32px, 3.4vw, 46px);
  line-height: .92; letter-spacing: -.02em; text-transform: uppercase;
  margin: 7px 0 8px;
}
.view-sub { max-width: 670px; color: var(--muted); font-size: 12.5px; line-height: 1.55; }
.head-status, .head-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.status-chip {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 9px; border: 1px solid var(--line);
  background: rgba(255, 255, 255, .018);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .06em;
  color: var(--muted); text-transform: uppercase; white-space: nowrap;
}
.status-chip .icon { color: var(--dim); }
.status-chip.is-hot, .status-chip.is-critical { color: #ff9c9c; border-color: #5b2c2f; background: rgba(232, 69, 69, .08); }
.status-chip.is-critical { animation: heatPulse 1.8s infinite; }

.section-head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px;
  margin: 24px 0 12px;
}
.section-head h2 { font-family: var(--font-display); font-size: 22px; text-transform: uppercase; line-height: 1; }
.section-head--boss { margin-top: 34px; }
.section-note { font-family: var(--font-mono); font-size: 8px; color: var(--dim); letter-spacing: .08em; text-transform: uppercase; }

.alert-banner {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 14px; margin: 0 0 16px;
  border: 1px solid #5c3b28; background: linear-gradient(90deg, rgba(232, 154, 75, .12), rgba(232, 154, 75, .03));
  color: var(--orange);
}
.alert-banner .icon { flex: 0 0 auto; }
.alert-banner div { display: grid; gap: 2px; flex: 1; min-width: 0; }
.alert-banner strong { font-family: var(--font-mono); font-size: 9.5px; letter-spacing: .1em; }
.alert-banner span { font-size: 11px; color: var(--muted); line-height: 1.4; }
.alert-banner.is-critical { border-color: #7b2c31; background: linear-gradient(90deg, rgba(232, 69, 69, .17), rgba(232, 69, 69, .04)); color: var(--red-2); }
.alert-banner .btn { flex: 0 0 auto; }

.base-layout, .ops-layout { display: grid; grid-template-columns: minmax(0, 1fr) 286px; gap: 22px; align-items: start; }
.base-col, .ops-list { min-width: 0; }
.rail { display: grid; gap: 14px; position: sticky; top: 86px; }
.rail .panel { padding: 15px; }

/* reward chips */
.reward-chip {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 7px 9px; border: 1px solid var(--line); background: rgba(255, 255, 255, .018);
  min-width: 0;
}
.reward-chip .icon { color: var(--dim); }
.reward-chip span { display: grid; gap: 1px; }
.reward-chip em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .13em; color: var(--dim); }
.reward-chip strong { font-family: var(--font-mono); font-size: 10px; color: var(--text); white-space: nowrap; }
.reward-chip.is-hot .icon, .reward-chip.is-hot strong { color: #ff9d7a; }

.type-badge {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 6px; border: 1px solid color-mix(in srgb, var(--tc) 45%, var(--line));
  background: color-mix(in srgb, var(--tc) 9%, transparent);
  font-family: var(--font-mono); font-size: 7px; letter-spacing: .06em;
  color: color-mix(in srgb, var(--tc) 75%, white); text-transform: uppercase;
  white-space: nowrap;
}
.type-badge i { width: 5px; height: 5px; border-radius: 50%; background: var(--tc); box-shadow: 0 0 6px var(--tc); }

.pips { display: flex; gap: 3px; }
.pip { width: 13px; height: 4px; background: #2a3039; }
.pip.is-on { background: var(--fac, var(--gold)); box-shadow: 0 0 6px -1px var(--fac, var(--gold)); }

/* mobile adjustments */
@media (max-width: 900px) {
  .topbar { height: auto; min-height: 58px; padding: 9px 14px; flex-wrap: wrap; gap: 8px 12px; }
  .brand-wrap { min-width: 0; flex: 1; }
  .brand { font-size: 12px; gap: 6px; }
  .brand-r { width: 21px; height: 21px; font-size: 15px; }
  .brand-team { font-size: 8px; }
  .brand-sub { padding-left: 27px; font-size: 6.5px; }
  .topres { order: 3; width: 100%; display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
  .res { padding: 5px 7px; gap: 5px; justify-content: center; }
  .res-label { display: none; }
  .res strong { font-size: 9.5px; }
  .res .icon { width: 12px; height: 12px; }
  .topactions { gap: 5px; }
  .icon-btn { width: 32px; height: 32px; }
  .shell { grid-template-columns: 1fr; }
  .sidebar { display: none; }
  .view { padding: 18px 14px calc(84px + env(safe-area-inset-bottom)); }
  .mobile-nav { display: grid; }
  .toast-root { bottom: calc(78px + env(safe-area-inset-bottom)); right: 12px; left: 12px; align-items: stretch; }
  .toast { max-width: none; }
  .view-head { display: block; }
  .view-head h1 { font-size: 34px; margin-top: 6px; }
  .view-sub { font-size: 12px; }
  .head-status, .head-actions { justify-content: flex-start; margin-top: 12px; }
  .head-actions .btn { flex: 1; }
  .base-layout, .ops-layout { grid-template-columns: 1fr; }
  .rail { position: static; }
  .section-head { align-items: flex-start; }
  .alert-banner { flex-wrap: wrap; }
  .alert-banner .btn { width: 100%; }
  .intro { padding: 14px; align-items: start; }
  .intro-card { grid-template-columns: 1fr; min-height: 0; }
  .intro-copy { padding: 30px 22px 26px; }
  .intro-art { display: none; }
  .intro-logo h1 { font-size: clamp(54px, 16vw, 82px); }
  .intro-logo { gap: 15px; margin-top: 18px; }
  .logo-mark { width: 58px; height: 58px; font-size: 38px; }
  .intro-story p { font-size: 13px; }
  .intro-steps { gap: 6px; }
  .intro-steps span { padding: 8px; font-size: 8px; }
  .btn-start { width: 100%; }
  .intro-save { width: 100%; font-size: 8.5px; }
  .intro-foot { font-size: 7px; }
  .intro-foot span:last-child { display: none; }
}
@media (max-width: 480px) {
  .brand-team { display: none; }
  .res { padding: 5px 5px; }
  .res strong { font-size: 9px; }
  .intro-card { clip-path: none; }
}

/* ------------------------------------------------------------------ diorama */
.diorama { position: relative; overflow: hidden; padding: 0; }
.diorama .base-svg { display: block; width: 100%; height: auto; min-height: 218px; }
.diorama::after {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(180deg, transparent 62%, rgba(7, 8, 10, .6));
}
.diorama.is-hot { box-shadow: inset 0 0 0 1px rgba(232, 69, 69, .38), inset 0 0 80px rgba(232, 69, 69, .12), var(--shadow); }
.diorama-tag {
  position: absolute; left: 14px; bottom: 12px; z-index: 2;
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 8px; border: 1px solid var(--line-2);
  background: rgba(8, 10, 13, .8);
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .13em;
  color: var(--muted); text-transform: uppercase;
}
.svg-kicker { font-family: var(--font-mono); font-size: 9px; font-weight: 700; letter-spacing: .16em; fill: #f0c75e; }
.svg-sub { font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .1em; fill: #737c88; }
.svg-r { font-family: var(--font-display); font-size: 27px; font-weight: 900; fill: #ff5a5a; }
.win { fill: #20262f; }
.win.is-lit { fill: #e8bb4f; filter: drop-shadow(0 0 3px rgba(240, 199, 94, .45)); }
.beacon { fill: #ff4a4a; animation: beaconBlink 2.2s infinite; }
@keyframes beaconBlink { 0%, 72%, 100% { opacity: .45; } 78%, 88% { opacity: 1; } }

/* ------------------------------------------------------------------ facilities */
.facility-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 11px; }
.facility-card {
  position: relative;
  display: flex; flex-direction: column;
  padding: 14px;
  border: 1px solid var(--line);
  background:
    linear-gradient(150deg, color-mix(in srgb, var(--fac) 7%, transparent), transparent 42%),
    var(--panel);
  transition: border-color .16s ease, transform .16s ease;
  min-height: 188px;
}
.facility-card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, var(--fac), transparent 75%);
  opacity: .75;
}
.facility-card:hover { border-color: color-mix(in srgb, var(--fac) 38%, var(--line)); transform: translateY(-1px); }
.facility-card.is-locked { opacity: .58; }
.facility-card.is-locked:hover { transform: none; border-color: var(--line); }
.facility-top { display: flex; align-items: flex-start; gap: 11px; }
.facility-icon {
  width: 42px; height: 42px; flex: 0 0 auto;
  display: grid; place-items: center;
  border: 1px solid color-mix(in srgb, var(--fac) 45%, var(--line));
  background: color-mix(in srgb, var(--fac) 10%, transparent);
  color: var(--fac);
}
.facility-name { min-width: 0; flex: 1; }
.factitle-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.facility-name h3 { font-family: var(--font-display); font-size: 15.5px; line-height: 1.1; text-transform: uppercase; }
.facility-lv { font-family: var(--font-mono); font-size: 8px; color: var(--muted); letter-spacing: .06em; white-space: nowrap; }
.facility-lv em { font-style: normal; color: var(--dim); }
.facility-name .pips { margin-top: 6px; }
.facility-blurb { margin: 12px 0 8px; color: var(--dim); font-size: 10.5px; line-height: 1.5; flex: 1; }
.facility-effect {
  display: grid; gap: 2px; padding: 8px 0 10px;
  border-top: 1px solid rgba(255, 255, 255, .05);
  font-family: var(--font-mono); font-size: 7.5px; line-height: 1.45;
  color: var(--muted); letter-spacing: .025em;
}
.facility-effect em { font-style: normal; color: var(--dim); }
.btn-facility { width: 100%; justify-content: flex-start; padding: 8px 10px; font-size: 8.5px; color: var(--muted); background: rgba(255, 255, 255, .02); }
.btn-facility:hover { color: var(--text); }
.btn-facility.is-disabled { color: var(--dim); }
.btn-facility.is-maxed { color: var(--green); border-color: #2d4639; }

/* expansions */
.expansion-intro {
  display: flex; align-items: center; justify-content: space-between; gap: 18px;
  padding: 14px 16px; margin-bottom: 12px;
  border: 1px solid #4b3d22; background: linear-gradient(90deg, rgba(240, 199, 94, .09), transparent 72%);
}
.expansion-intro p { font-size: 11.5px; line-height: 1.55; color: var(--muted); max-width: 660px; }
.expansion-intro.is-complete { border-color: #6b5427; background: linear-gradient(90deg, rgba(240, 199, 94, .13), transparent 76%); }
.expansion-intro .btn { flex: 0 0 auto; }
.expansion-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 11px; }
.expansion-card {
  padding: 15px;
  border: 1px solid var(--line);
  background:
    linear-gradient(155deg, color-mix(in srgb, var(--exp) 8%, transparent), transparent 46%),
    var(--panel);
  position: relative;
}
.expansion-card::before {
  content: ""; position: absolute; top: 0; left: 0; right: 0; height: 2px;
  background: linear-gradient(90deg, var(--exp), transparent);
}
.expansion-card.is-owned { border-color: color-mix(in srgb, var(--exp) 35%, var(--line)); }
.expansion-head { display: flex; align-items: flex-start; gap: 10px; }
.expansion-icon {
  width: 40px; height: 40px; flex: 0 0 auto;
  display: grid; place-items: center; color: var(--exp);
  border: 1px solid color-mix(in srgb, var(--exp) 42%, var(--line));
  background: color-mix(in srgb, var(--exp) 9%, transparent);
}
.expansion-head h3 { font-family: var(--font-display); font-size: 16px; text-transform: uppercase; line-height: 1.1; margin-top: 3px; }
.owned-stamp {
  margin-left: auto; display: inline-flex; align-items: center; gap: 3px;
  padding: 3px 5px; font-family: var(--font-mono); font-size: 6.5px;
  letter-spacing: .08em; color: var(--green); border: 1px solid #2f503d;
}
.expansion-card > p { margin: 11px 0 8px; color: var(--dim); font-size: 10.5px; line-height: 1.5; min-height: 46px; }
.expansion-bonus {
  padding: 7px 8px; margin-bottom: 10px;
  border: 1px dashed color-mix(in srgb, var(--exp) 30%, var(--line));
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .03em;
  color: color-mix(in srgb, var(--exp) 65%, var(--muted));
}
.expansion-card .btn { width: 100%; font-size: 8.5px; }
.expansion-built { font-family: var(--font-mono); font-size: 7.5px; color: var(--green); padding: 7px 0; }
.expansion-locked {
  display: flex; align-items: center; gap: 15px; padding: 17px;
  color: var(--dim);
}
.expansion-locked > .icon { color: var(--gold); opacity: .7; }
.expansion-locked div:nth-child(2) { display: grid; gap: 3px; flex: 1; }
.expansion-locked strong { font-family: var(--font-mono); font-size: 10px; letter-spacing: .1em; color: var(--muted); }
.expansion-locked span { font-size: 11px; line-height: 1.45; }
.locked-preview { display: flex; gap: 7px; flex-wrap: wrap; }
.locked-preview span {
  display: inline-flex; align-items: center; gap: 5px; padding: 5px 7px;
  border: 1px solid var(--line); font-family: var(--font-mono); font-size: 7px;
  color: var(--dim); letter-spacing: .05em; text-transform: uppercase;
}

/* rail */
.promo-panel { position: relative; overflow: hidden; }
.promo-panel.is-ready { border-color: #67552b; background: linear-gradient(150deg, rgba(240, 199, 94, .11), transparent 58%), var(--panel); }
.promo-panel h3 { font-family: var(--font-display); font-size: 25px; text-transform: uppercase; line-height: 1; margin: 6px 0 5px; }
.promo-panel p { color: var(--dim); font-size: 10.5px; line-height: 1.5; }
.promo-reward { display: flex; align-items: center; gap: 6px; margin: 11px 0; font-family: var(--font-mono); font-size: 9px; color: var(--gold); }
.promo-rank-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin: 5px 0 8px; }
.promo-rank-row span { font-family: var(--font-mono); font-size: 7.5px; color: var(--dim); }
.promo-next { margin-top: 9px; font-family: var(--font-mono); font-size: 7.5px; line-height: 1.5; color: var(--dim); letter-spacing: .02em; }
.promo-next strong { color: var(--muted); }
.ladder { display: flex; justify-content: space-between; gap: 3px; margin-top: 13px; padding-top: 11px; border-top: 1px solid rgba(255, 255, 255, .05); }
.ladder-step { display: grid; justify-items: center; gap: 4px; flex: 1; opacity: .44; }
.ladder-step i { width: 6px; height: 6px; border-radius: 50%; background: #353c46; }
.ladder-step em { font-style: normal; font-family: var(--font-mono); font-size: 5.5px; letter-spacing: .02em; color: var(--dim); }
.ladder-step.is-done { opacity: 1; }
.ladder-step.is-done i { background: var(--gold); box-shadow: 0 0 6px rgba(240, 199, 94, .5); }
.ladder-step.is-next i { background: var(--red); box-shadow: 0 0 8px rgba(232, 69, 69, .6); }
.quick-panel .panel-head { margin-bottom: 10px; }
.quick-action {
  display: flex; align-items: center; gap: 10px; width: 100%;
  padding: 10px 0; border: 0; border-top: 1px solid rgba(255, 255, 255, .055);
  background: transparent; color: var(--text); text-align: left; cursor: pointer;
}
.quick-action:first-of-type { border-top: 0; }
.quick-action:hover .quick-cost { color: var(--gold); }
.quick-icon { width: 33px; height: 33px; flex: 0 0 auto; display: grid; place-items: center; border: 1px solid var(--line); }
.quick-icon--heat { color: var(--orange); border-color: #4b3827; background: rgba(232, 154, 75, .06); }
.quick-icon--ball { color: var(--muted); }
.quick-copy { display: grid; gap: 1px; flex: 1; min-width: 0; }
.quick-copy strong { font-size: 11px; }
.quick-copy em { font-style: normal; font-family: var(--font-mono); font-size: 7.5px; color: var(--dim); }
.quick-cost { font-family: var(--font-mono); font-size: 9px; color: var(--muted); }
.quick-foot { margin-top: 8px; padding-top: 9px; border-top: 1px solid rgba(255, 255, 255, .05); font-family: var(--font-mono); font-size: 7px; line-height: 1.5; color: var(--dim); }
.crew-panel .panel-head { margin-bottom: 9px; }
.crew-feature { display: flex; align-items: center; gap: 11px; padding: 10px 0 12px; }
.crew-sprite {
  width: 76px; height: 76px; flex: 0 0 auto; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 38%, color-mix(in srgb, var(--tc) 24%, transparent), transparent 70%);
  border: 1px solid color-mix(in srgb, var(--tc) 28%, var(--line));
}
.crew-sprite .poke-sprite { width: 76px; height: 76px; }
.crew-feature h3 { font-family: var(--font-display); font-size: 19px; text-transform: uppercase; line-height: 1; margin-bottom: 5px; }
.crew-feature p { margin-top: 5px; color: var(--dim); font-size: 8.5px; line-height: 1.4; }
.crew-line { display: flex; justify-content: space-between; gap: 8px; padding: 6px 0; border-top: 1px solid rgba(255, 255, 255, .055); font-family: var(--font-mono); font-size: 8px; color: var(--dim); }
.crew-line strong { color: var(--muted); }
.crew-panel .btn { margin-top: 10px; }
.intel-panel p { margin-top: 7px; color: var(--dim); font-size: 10.5px; line-height: 1.55; }
.intel-panel .eyebrow { color: var(--gold); }

/* ------------------------------------------------------------------ missions */
.ops-list { display: grid; gap: 12px; }
.mission-card {
  display: grid;
  grid-template-columns: 156px minmax(0, 1fr) 196px;
  border: 1px solid var(--line);
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--tc) 5%, transparent), transparent 34%),
    var(--panel);
  overflow: hidden;
  transition: border-color .16s ease, transform .16s ease;
}
.mission-card:hover { border-color: color-mix(in srgb, var(--tc) 34%, var(--line)); transform: translateY(-1px); }
.mission-art {
  position: relative; display: flex; align-items: center; justify-content: center;
  min-height: 178px; padding: 12px;
  background:
    radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--tc) 26%, transparent), transparent 66%),
    repeating-linear-gradient(-45deg, transparent 0 14px, rgba(255, 255, 255, .014) 14px 15px),
    #0d1014;
  border-right: 1px solid var(--line);
  overflow: hidden;
}
.mission-halo {
  position: absolute; width: 112px; height: 112px; border-radius: 50%;
  border: 1px dashed color-mix(in srgb, var(--tc) 38%, transparent);
  animation: haloSpin 30s linear infinite;
}
.mission-halo::after {
  content: ""; position: absolute; inset: 12px; border: 1px solid color-mix(in srgb, var(--tc) 18%, transparent); border-radius: 50%;
}
@keyframes haloSpin { to { transform: rotate(360deg); } }
.mission-art .poke-sprite { position: relative; z-index: 1; filter: drop-shadow(0 10px 18px rgba(0, 0, 0, .4)); }
.mission-index {
  position: absolute; top: 9px; left: 10px;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: .1em; color: var(--dim);
}
.mission-tier {
  position: absolute; bottom: 9px; left: 10px;
  font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .12em; color: color-mix(in srgb, var(--tc) 65%, var(--muted));
}
.mission-body { padding: 14px 16px 13px; min-width: 0; }
.mission-topline { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.mission-loc {
  display: inline-flex; align-items: center; gap: 5px;
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .09em;
  color: var(--muted); text-transform: uppercase;
}
.mission-loc .icon { color: var(--dim); }
.mission-tag {
  margin-left: auto; padding: 3px 6px; border: 1px solid var(--line);
  font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .09em;
  color: var(--dim); text-transform: uppercase; white-space: nowrap;
}
.tag--hot { color: #ff9d7a; border-color: #5c3627; background: rgba(232, 154, 75, .07); }
.tag--cool { color: var(--teal); border-color: #2a4a46; background: rgba(104, 214, 194, .06); }
.tag--gold { color: var(--gold); border-color: #5a4925; background: rgba(240, 199, 94, .07); }
.tag--none { color: #5e6672; }
.mission-title-row { display: flex; align-items: center; gap: 9px; margin: 6px 0 2px; flex-wrap: wrap; }
.mission-title-row h3 { font-family: var(--font-display); font-size: 25px; line-height: 1; text-transform: uppercase; }
.rarity { margin-left: auto; color: color-mix(in srgb, var(--tc) 65%, var(--gold)); font-size: 8px; letter-spacing: 2px; }
.mission-flavor { color: var(--dim); font-size: 10.5px; line-height: 1.45; margin: 4px 0 10px; }
.mission-stat-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
.mission-stat-grid .reward-chip { padding: 6px 7px; }
.mission-stat-grid .reward-chip strong { font-size: 9px; }
.mission-meta-row { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; margin-top: 9px; }
.threat { display: inline-flex; align-items: center; gap: 7px; }
.threat em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .09em; color: var(--dim); }
.bar-pips { display: flex; gap: 2px; }
.bar-pips i { width: 9px; height: 4px; background: #2a3039; }
.bar-pips i.is-on { background: var(--red); }
.bar-pips--gold i.is-on { background: var(--gold); }
.rooms-left { display: inline-flex; align-items: center; gap: 5px; margin-left: auto; font-family: var(--font-mono); font-size: 7px; color: var(--dim); }
.mission-tag-desc { margin-top: 6px; font-family: var(--font-mono); font-size: 7px; color: var(--dim); }
.mission-cta {
  display: flex; flex-direction: column; justify-content: center; gap: 8px;
  padding: 14px; border-left: 1px solid var(--line);
  background: rgba(0, 0, 0, .13);
}
.mission-cta .btn { font-size: 8.5px; padding: 10px 8px; }
.mission-sub { text-align: center; font-family: var(--font-mono); font-size: 6.5px; color: var(--dim); letter-spacing: .06em; }
.mission-card--final {
  border-color: #6d5425;
  background:
    linear-gradient(120deg, rgba(240, 199, 94, .09), transparent 44%),
    repeating-linear-gradient(-45deg, transparent 0 22px, rgba(240, 199, 94, .013) 22px 23px),
    #111318;
  box-shadow: 0 0 40px -18px rgba(240, 199, 94, .35);
}
.mission-card--final .mission-art { border-right-color: #4d3f23; background: radial-gradient(circle at 50% 45%, rgba(240, 199, 94, .17), transparent 65%), #0d1014; }
.mission-card--final .mission-index, .mission-card--final .mission-tier { color: var(--gold); }
.mission-card--final .mission-title-row h3 { color: var(--gold-2); }
.mission-card--final .mission-cta { border-left-color: #4d3f23; background: rgba(240, 199, 94, .035); }
.mission-card--final .rarity { color: var(--gold); }
.mission-card--final .mission-flavor { color: #aaa184; }

/* ops rail */
.partner-card .panel-head { margin-bottom: 8px; }
.partner-hero { display: flex; align-items: center; gap: 10px; padding: 8px 0 12px; }
.partner-hero-sprite {
  width: 88px; height: 88px; flex: 0 0 auto; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--tc) 25%, transparent), transparent 70%);
  border: 1px solid color-mix(in srgb, var(--tc) 30%, var(--line));
}
.partner-hero-sprite .poke-sprite { width: 88px; height: 88px; }
.partner-hero h3 { font-family: var(--font-display); font-size: 20px; text-transform: uppercase; line-height: 1; margin-bottom: 5px; }
.partner-hero p { margin-top: 5px; color: var(--dim); font-size: 8.5px; line-height: 1.4; }
.mini-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.mini-stats span { display: grid; gap: 4px; justify-items: center; }
.mini-stats em { font-style: normal; font-family: var(--font-mono); font-size: 7px; color: var(--dim); }
.mini-stats i { width: 100%; height: 3px; background: #252b34; position: relative; overflow: hidden; }
.mini-stats i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--v); background: linear-gradient(90deg, #a13037, var(--red)); }
.partner-note { margin: 11px 0 9px; padding-top: 9px; border-top: 1px solid rgba(255, 255, 255, .055); font-family: var(--font-mono); font-size: 7px; line-height: 1.5; color: var(--dim); }
.gear-panel .panel-head { margin-bottom: 8px; }
.gear-line { display: flex; justify-content: space-between; align-items: center; gap: 8px; padding: 8px 0; border-top: 1px solid rgba(255, 255, 255, .055); font-size: 10px; color: var(--muted); }
.gear-line:first-of-type { border-top: 0; }
.gear-line span { display: inline-flex; align-items: center; gap: 6px; }
.gear-line strong { font-family: var(--font-mono); font-size: 10px; color: var(--text); }
.gear-panel .btn { margin-top: 8px; }
.heat-panel strong { font-family: var(--font-mono); font-size: 12px; color: var(--text); }
.heat-panel p { margin: 8px 0 10px; font-family: var(--font-mono); font-size: 7.5px; line-height: 1.5; color: var(--dim); }
.heat-panel.is-hot, .heat-panel.is-critical { border-color: #5b2c2f; }
.heat-panel.is-critical { animation: heatPulse 1.8s infinite; }

/* ------------------------------------------------------------------ roster */
.capacity-panel { display: grid; grid-template-columns: 1fr 1.2fr auto; gap: 22px; align-items: center; padding: 15px 17px; margin-bottom: 16px; }
.capacity-copy { display: grid; gap: 2px; }
.capacity-copy strong { font-family: var(--font-display); font-size: 24px; line-height: 1; color: var(--text); }
.capacity-copy strong em { font-style: normal; color: var(--dim); font-size: 15px; }
.capacity-copy span { font-family: var(--font-mono); font-size: 7.5px; color: var(--dim); }
.capacity-meter .meter { height: 9px; }
.capacity-side { display: grid; gap: 3px; text-align: right; }
.capacity-side span { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .12em; color: var(--dim); }
.capacity-side strong { font-family: var(--font-mono); font-size: 9px; color: var(--gold); }
.roster-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.mon-card {
  display: grid; grid-template-columns: 144px minmax(0, 1fr);
  border: 1px solid var(--line);
  background:
    linear-gradient(130deg, color-mix(in srgb, var(--tc) 5%, transparent), transparent 40%),
    var(--panel);
  overflow: hidden;
  transition: border-color .16s ease;
}
.mon-card:hover { border-color: color-mix(in srgb, var(--tc) 30%, var(--line)); }
.mon-card.is-active { border-color: #5b4a27; box-shadow: inset 0 0 0 1px rgba(240, 199, 94, .12); }
.mon-art {
  position: relative; display: flex; align-items: center; justify-content: center;
  min-height: 228px; padding: 10px;
  background:
    radial-gradient(circle at 50% 42%, color-mix(in srgb, var(--tc) 24%, transparent), transparent 68%),
    repeating-linear-gradient(-45deg, transparent 0 14px, rgba(255, 255, 255, .012) 14px 15px),
    #0c0f13;
  border-right: 1px solid var(--line);
}
.mon-halo { position: absolute; width: 100px; height: 100px; border-radius: 50%; border: 1px dashed color-mix(in srgb, var(--tc) 32%, transparent); }
.mon-art .poke-sprite { position: relative; z-index: 1; }
.mon-power {
  position: absolute; top: 9px; right: 8px;
  padding: 3px 5px; border: 1px solid color-mix(in srgb, var(--tc) 35%, var(--line));
  background: rgba(8, 10, 13, .72);
  font-family: var(--font-mono); font-size: 6.5px; color: color-mix(in srgb, var(--tc) 70%, white);
}
.mon-starter, .mon-trophy {
  position: absolute; top: 9px; left: 8px;
  font-family: var(--font-mono); font-size: 5.5px; letter-spacing: .08em;
  padding: 2px 4px; border: 1px solid #3b424d; color: var(--dim); background: rgba(8, 10, 13, .7);
}
.mon-trophy { color: var(--gold); border-color: #5f4d27; }
.deployed-stamp {
  position: absolute; bottom: 9px; left: 8px;
  padding: 3px 5px; border: 1px solid #47652f; color: var(--green);
  background: rgba(8, 10, 13, .8); font-family: var(--font-mono); font-size: 5.5px; letter-spacing: .1em;
}
.mon-body { padding: 13px 13px 12px; min-width: 0; display: flex; flex-direction: column; }
.mon-title-row { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; }
.mon-title-row h3 { font-family: var(--font-display); font-size: 21px; line-height: 1; text-transform: uppercase; }
.mon-ability { display: flex; align-items: center; gap: 5px; margin-top: 7px; font-family: var(--font-mono); font-size: 7.5px; color: var(--gold); }
.mon-tagline { margin: 5px 0 9px; color: var(--dim); font-size: 9.5px; line-height: 1.45; flex: 1; }
.mon-stats { display: grid; gap: 5px; }
.mon-stat { display: grid; grid-template-columns: 32px 1fr 16px; align-items: center; gap: 6px; }
.mon-stat span { font-family: var(--font-mono); font-size: 5.5px; letter-spacing: .06em; color: var(--dim); }
.mon-stat i { height: 3px; background: #252b34; display: block; position: relative; overflow: hidden; }
.mon-stat i b { display: block; height: 100%; background: linear-gradient(90deg, #92313a, var(--red)); }
.mon-stat strong { font-family: var(--font-mono); font-size: 7px; color: var(--muted); text-align: right; }
.mon-actions { display: flex; gap: 5px; margin-top: 10px; flex-wrap: wrap; }
.mon-actions .btn { flex: 1; min-width: 0; padding: 7px 6px; font-size: 7px; }
.active-label { display: inline-flex; align-items: center; gap: 4px; font-family: var(--font-mono); font-size: 7px; color: var(--green); text-transform: uppercase; }
.btn-fence { color: var(--dim); }
.empty-slot {
  display: grid; place-items: center; gap: 5px; align-content: center;
  min-height: 150px; padding: 18px;
  border: 1px dashed #2d343e; background: rgba(255, 255, 255, .008);
  color: #4f5762;
}
.empty-slot > span { width: 46px; height: 46px; display: grid; place-items: center; border: 1px dashed #333b45; }
.empty-slot strong { font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .12em; }
.empty-slot em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; color: #414852; }
.roster-foot { display: flex; gap: 18px; flex-wrap: wrap; margin-top: 16px; padding-top: 12px; border-top: 1px solid var(--line); }
.foot-note { display: inline-flex; align-items: center; gap: 6px; font-family: var(--font-mono); font-size: 7px; color: var(--dim); }
.foot-note .icon { color: var(--gold); }

/* ------------------------------------------------------------------ shared sprite */
.poke-sprite { display: block; overflow: visible; }

/* ------------------------------------------------------------------ heist */
.heist-view { max-width: 1220px; }
.heist-view--final .heist-head h1 { color: var(--gold-2); }
.heist-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 22px; margin-bottom: 18px; }
.heist-head h1 {
  font-family: var(--font-display); font-size: clamp(32px, 3.7vw, 50px);
  line-height: .9; text-transform: uppercase; letter-spacing: -.02em; margin: 7px 0 8px;
}
.heist-head .view-sub { max-width: 680px; }
.heist-live {
  display: flex; align-items: center; gap: 10px; flex: 0 0 auto;
  padding: 9px 12px; border: 1px solid var(--line-2);
  background: rgba(232, 69, 69, .04);
}
.heist-live div { display: grid; gap: 2px; }
.heist-live em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .14em; color: var(--dim); }
.heist-live strong { font-family: var(--font-mono); font-size: 9px; letter-spacing: .08em; color: var(--red-2); }
.heist-live strong.is-clean { color: var(--green); }
.heist-live strong.is-warm { color: var(--gold); }
.heist-live strong.is-hot { color: #ff9a68; }

.heist-grid { display: grid; grid-template-columns: minmax(0, 1.38fr) minmax(330px, .82fr); gap: 16px; align-items: start; }
.heist-main, .heist-side { display: grid; gap: 12px; min-width: 0; }

/* target */
.target-band {
  display: flex; align-items: center; gap: 16px;
  padding: 15px 16px;
  background:
    radial-gradient(circle at 9% 50%, color-mix(in srgb, var(--tc) 20%, transparent), transparent 38%),
    linear-gradient(120deg, color-mix(in srgb, var(--tc) 6%, transparent), transparent 44%),
    var(--panel);
}
.target-art {
  position: relative; width: 118px; height: 118px; flex: 0 0 auto;
  display: grid; place-items: center;
}
.target-halo {
  position: absolute; width: 104px; height: 104px; border-radius: 50%;
  border: 1px dashed color-mix(in srgb, var(--tc) 40%, transparent);
  animation: haloSpin 32s linear infinite;
}
.target-halo::after { content: ""; position: absolute; inset: 12px; border: 1px solid color-mix(in srgb, var(--tc) 16%, transparent); border-radius: 50%; }
.target-art .poke-sprite { position: relative; z-index: 1; }
.target-copy { flex: 1; min-width: 0; }
.target-title { display: flex; align-items: center; gap: 9px; margin: 3px 0 5px; flex-wrap: wrap; }
.target-title h2 { font-family: var(--font-display); font-size: clamp(27px, 2.7vw, 37px); line-height: .9; text-transform: uppercase; }
.target-copy > p { color: var(--dim); font-size: 10.5px; line-height: 1.45; }
.target-meta { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 8px; }
.target-meta > span { display: inline-flex; align-items: center; gap: 5px; font-family: var(--font-mono); font-size: 7px; color: var(--muted); }
.target-meta .mission-tag { margin-left: 0; }
.target-chance {
  flex: 0 0 auto; display: grid; justify-items: end; gap: 1px;
  padding-left: 16px; border-left: 1px solid var(--line);
}
.target-chance em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .13em; color: var(--dim); }
.target-chance strong { font-family: var(--font-display); font-size: 31px; line-height: 1; color: var(--gold); }
.target-chance span { font-family: var(--font-mono); font-size: 7px; color: var(--dim); }

/* map */
.map-panel { padding: 13px 15px 12px; }
.map-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .13em; color: var(--dim); }
.map-center { color: var(--muted); }
.map-track {
  position: relative; height: 38px; margin: 13px 8px 9px;
  background: linear-gradient(180deg, #0b0e12, #10141a);
  border-top: 1px solid #2d343e; border-bottom: 1px solid #2d343e;
}
.map-track::before {
  content: ""; position: absolute; top: 50%; left: 0; right: 0; height: 1px;
  background: repeating-linear-gradient(90deg, #353d48 0 5px, transparent 5px 10px);
}
.map-fill {
  position: absolute; top: calc(50% - 1px); left: 0; height: 2px;
  background: linear-gradient(90deg, #7b2a30, var(--red));
  box-shadow: 0 0 10px rgba(232, 69, 69, .5);
  transition: width .35s ease;
}
.map-node {
  position: absolute; top: 50%; width: 6px; height: 6px; border-radius: 50%;
  transform: translate(-50%, -50%);
  background: #252b34; border: 1px solid #3c4551;
}
.map-node.is-done { background: var(--red); border-color: #ff7373; box-shadow: 0 0 6px rgba(232, 69, 69, .6); }
.map-node.is-current { border-color: var(--gold); box-shadow: 0 0 8px rgba(240, 199, 94, .5); }
.map-actor {
  position: absolute; top: 50%; z-index: 3;
  transform: translate(-50%, -50%);
  width: 24px; height: 24px; display: grid; place-items: center;
  border: 1px solid #ff7676; background: #1c0f11;
  box-shadow: 0 0 16px -3px rgba(232, 69, 69, .75);
  transition: left .35s ease;
}
.map-actor::after {
  content: ""; position: absolute; inset: -6px; border: 1px solid rgba(232, 69, 69, .22);
  animation: actorPulse 1.8s infinite;
}
.map-actor i { font-style: normal; font-family: var(--font-display); font-size: 12px; color: var(--red-2); }
@keyframes actorPulse { 0%, 100% { transform: scale(1); opacity: .6; } 50% { transform: scale(1.18); opacity: .15; } }
.map-target {
  position: absolute; top: 50%; right: -10px; z-index: 2;
  transform: translateY(-50%);
  width: 26px; height: 26px; display: grid; place-items: center;
  border: 1px solid #6b5527; background: #141006; color: var(--gold);
}
.map-legend { display: flex; gap: 14px; font-family: var(--font-mono); font-size: 6.5px; color: var(--dim); }
.map-legend span { display: inline-flex; align-items: center; gap: 5px; }
.legend-dot { width: 5px; height: 5px; border-radius: 50%; background: #333b45; display: inline-block; }
.legend-dot.is-done { background: var(--red); }
.legend-dot.is-mark { background: var(--gold); }

/* suspicion */
.alert-panel { padding: 13px 15px; }
.alert-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.alert-head strong { font-family: var(--font-display); font-size: 27px; line-height: 1; color: var(--text); }
.alert-head strong em { font-style: normal; font-size: 13px; color: var(--dim); }
.alert-panel.is-hot .alert-head strong { color: #ff9a68; }
.alert-panel.is-critical .alert-head strong { color: var(--red-2); }
.alert-bar {
  position: relative; height: 11px; margin: 10px 0 8px;
  background: #1a1f26; border: 1px solid #2d343e; overflow: visible;
}
.alert-fill {
  display: block; height: 100%;
  background: linear-gradient(90deg, #3e8d65, #b9a540 48%, #e84545 82%);
  transition: width .35s ease;
}
.alert-mark { position: absolute; top: -3px; bottom: -3px; width: 1px; background: #424b57; }
.alert-mark em {
  position: absolute; top: -11px; left: 50%; transform: translateX(-50%);
  font-style: normal; font-family: var(--font-mono); font-size: 5.5px; color: #59626e;
}
.alert-mark--end em { left: auto; right: 0; transform: none; }
.alert-foot { display: flex; align-items: flex-start; gap: 7px; font-size: 9.5px; line-height: 1.45; color: var(--dim); }
.alert-foot .icon { margin-top: 1px; color: var(--dim); }
.alert-panel.is-clean .alert-foot .icon { color: var(--green); }
.alert-panel.is-critical .alert-foot { color: #c99090; }

.heist-chips { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; }
.heist-chip {
  display: flex; align-items: center; gap: 7px; min-width: 0;
  padding: 9px 10px; border: 1px solid var(--line); background: var(--panel);
  font-family: var(--font-mono); color: var(--muted);
}
.heist-chip .icon { color: var(--dim); }
.heist-chip em { font-style: normal; font-size: 6px; letter-spacing: .1em; color: var(--dim); display: block; }
.heist-chip strong { display: block; font-size: 9px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.heist-chip .poke-sprite { flex: 0 0 auto; }
.heist-chip.is-spent { opacity: .55; }

/* actions */
.action-panel { padding: 13px 13px 11px; }
.action-panel .panel-head { margin-bottom: 9px; }
.turn-count { font-family: var(--font-mono); font-size: 7px; letter-spacing: .1em; color: var(--dim); }
.action-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.heist-action {
  position: relative;
  display: grid; grid-template-columns: 13px 27px minmax(0, 1fr) auto;
  align-items: center; gap: 6px;
  padding: 8px 7px; min-height: 52px;
  border: 1px solid var(--line); background: rgba(255, 255, 255, .018);
  color: var(--text); text-align: left; cursor: pointer;
  transition: .14s ease;
  overflow: hidden;
}
.heist-action:hover { background: #1c222b; border-color: #4a5361; transform: translateY(-1px); }
.heist-action:active { transform: translateY(0); }
.ha-key {
  align-self: start; width: 13px; height: 13px; display: grid; place-items: center;
  border: 1px solid #363e49; font-family: var(--font-mono); font-size: 6px; color: var(--dim);
}
.ha-icon { color: var(--muted); display: grid; place-items: center; }
.ha-copy { display: grid; gap: 1px; min-width: 0; }
.ha-copy strong { font-family: var(--font-mono); font-size: 8.5px; letter-spacing: .04em; text-transform: uppercase; }
.ha-copy em { font-style: normal; font-family: var(--font-mono); font-size: 6px; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ha-badge {
  font-family: var(--font-mono); font-size: 7px; color: var(--dim);
  padding: 3px 5px; border: 1px solid #303741; background: rgba(0, 0, 0, .18); white-space: nowrap;
}
.ha-badge.good { color: var(--green); border-color: #2f4b3a; }
.ha-badge.bad { color: #ff9a68; border-color: #5b3928; }
.ha-badge.mid { color: var(--gold); border-color: #4c4228; }
.ha-badge.cold { color: var(--teal); border-color: #2b4a47; }
.ha-badge.gold { color: var(--gold); border-color: #5a4a28; }
.heist-action--ball { border-color: #4e4227; background: rgba(240, 199, 94, .035); }
.heist-action--ball .ha-icon { color: var(--gold); }
.heist-action--ball:hover { background: rgba(240, 199, 94, .08); border-color: #7a642f; }
.heist-action--bail { border-color: #3a2528; background: rgba(232, 69, 69, .025); }
.heist-action--bail .ha-icon { color: #b87878; }
.heist-action--bail:hover { border-color: #6b3a3f; background: rgba(232, 69, 69, .06); }
.heist-action.is-disabled { opacity: .35; cursor: not-allowed; transform: none; filter: grayscale(.5); }
.action-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  margin-top: 9px; padding-top: 8px; border-top: 1px solid rgba(255, 255, 255, .05);
  font-family: var(--font-mono); font-size: 6.5px; color: var(--dim);
}
.key-hint { color: #59626e; letter-spacing: .08em; }

/* log */
.log-panel { padding: 13px 13px 10px; }
.log-panel .panel-head { margin-bottom: 7px; }
.log-list { max-height: 252px; overflow-y: auto; display: grid; gap: 0; }
.log-entry { display: flex; gap: 8px; padding: 7px 5px; border-top: 1px solid rgba(255, 255, 255, .045); }
.log-entry:first-child { border-top: 0; }
.log-mark { width: 5px; height: 5px; border-radius: 50%; background: #4a5360; margin-top: 4px; flex: 0 0 auto; }
.log-entry p { font-family: var(--font-mono); font-size: 7.5px; line-height: 1.55; color: var(--dim); }
.log-entry.log--good .log-mark { background: var(--green); }
.log-entry.log--good p { color: #a8c2b2; }
.log-entry.log--bad .log-mark { background: var(--orange); }
.log-entry.log--bad p { color: #c9a18f; }
.log-entry.log--capture .log-mark { background: var(--gold); box-shadow: 0 0 6px var(--gold); }
.log-entry.log--capture p { color: var(--gold-2); }
.log-entry.log--warn .log-mark { background: var(--gold); }
.log-entry.log--warn p { color: #c4b385; }
.log-entry.is-new { background: rgba(255, 255, 255, .022); }

/* ------------------------------------------------------------------ modal */
body.modal-open { overflow: hidden; }
.modal-backdrop {
  position: fixed; inset: 0; z-index: 200;
  display: grid; place-items: center;
  padding: 24px;
  background: rgba(3, 4, 6, .78);
  backdrop-filter: blur(7px);
  animation: fadeIn .18s ease;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.modal {
  width: min(570px, 94vw);
  max-height: 90dvh;
  overflow-y: auto;
  border: 1px solid #3a424e;
  background:
    linear-gradient(150deg, rgba(255, 255, 255, .028), transparent 42%),
    #10141a;
  box-shadow: 0 50px 110px -30px #000, inset 0 1px 0 rgba(255, 255, 255, .05);
  animation: modalIn .22s cubic-bezier(.2, .9, .3, 1);
  position: relative;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}
@keyframes modalIn { from { opacity: 0; transform: translateY(14px) scale(.985); } to { opacity: 1; transform: none; } }
.modal--wide { width: min(980px, 96vw); }
.modal--result { width: min(790px, 95vw); background: #0d1015; }
.modal--promo { width: min(560px, 94vw); }
.modal--help { width: min(880px, 95vw); }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 18px; padding: 20px 22px 0; }
.modal-title { font-family: var(--font-display); font-size: 28px; line-height: .95; text-transform: uppercase; margin-top: 5px; }
.modal-x { width: 32px; height: 32px; flex: 0 0 auto; }
.modal-body { padding: 18px 22px 22px; }
.modal-head + .modal-body { padding-top: 15px; }

/* ------------------------------------------------------------------ prep */
.prep-grid { display: grid; grid-template-columns: .9fr 1.1fr; gap: 0; border: 1px solid var(--line); }
.prep-mission {
  padding: 18px; border-right: 1px solid var(--line);
  background:
    radial-gradient(circle at 50% 16%, color-mix(in srgb, var(--tc) 17%, transparent), transparent 52%),
    rgba(0, 0, 0, .14);
}
.prep-art { position: relative; height: 180px; display: grid; place-items: center; margin-bottom: 10px; }
.prep-art .target-halo { width: 145px; height: 145px; }
.prep-tier {
  position: absolute; bottom: 4px; left: 0;
  font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .12em; color: var(--dim);
}
.prep-mission h3 { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-family: var(--font-display); font-size: 28px; text-transform: uppercase; line-height: 1; margin: 5px 0 7px; }
.prep-mission > p { color: var(--dim); font-size: 10.5px; line-height: 1.5; }
.prep-tag { margin-top: 9px; padding: 7px 8px; border: 1px solid var(--line); font-family: var(--font-mono); font-size: 7px; line-height: 1.4; color: var(--muted); }
.prep-facts { display: grid; gap: 6px; margin: 12px 0; padding: 10px 0; border-top: 1px solid rgba(255, 255, 255, .055); border-bottom: 1px solid rgba(255, 255, 255, .055); }
.prep-facts span { display: flex; align-items: center; gap: 7px; font-family: var(--font-mono); font-size: 7.5px; color: var(--dim); }
.prep-facts .icon { color: var(--muted); }
.prep-rewards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; }
.prep-chance {
  display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap;
  margin-top: 12px; padding: 10px; border: 1px solid #5b4a28;
  background: rgba(240, 199, 94, .055);
}
.prep-chance span { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .09em; color: var(--dim); width: 100%; }
.prep-chance strong { font-family: var(--font-display); font-size: 25px; line-height: 1; color: var(--gold); }
.prep-chance em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; color: var(--dim); }
.prep-crew { padding: 18px; display: flex; flex-direction: column; }
.prep-crew-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; }
.prep-crew-head h3 { font-family: var(--font-display); font-size: 20px; text-transform: uppercase; line-height: 1; margin-top: 4px; }
.partner-options { display: grid; gap: 5px; margin: 13px 0 10px; max-height: 320px; overflow-y: auto; padding-right: 3px; }
.partner-option {
  display: grid; grid-template-columns: 52px 1fr; align-items: center; gap: 9px;
  padding: 7px 9px; border: 1px solid var(--line); background: rgba(255, 255, 255, .014);
  color: var(--text); text-align: left; cursor: pointer; transition: .14s ease;
}
.partner-option:hover { border-color: #4b5461; background: var(--panel-2); }
.partner-option.is-selected { border-color: #65542b; background: linear-gradient(90deg, rgba(240, 199, 94, .075), transparent); }
.po-sprite {
  width: 52px; height: 52px; display: grid; place-items: center;
  background: radial-gradient(circle at 50% 40%, color-mix(in srgb, var(--tc) 24%, transparent), transparent 70%);
  border: 1px solid color-mix(in srgb, var(--tc) 25%, var(--line));
}
.po-sprite .poke-sprite { width: 52px; height: 52px; }
.po-copy { display: grid; gap: 2px; min-width: 0; }
.po-name { display: flex; align-items: center; gap: 5px; font-family: var(--font-mono); font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; }
.po-name .icon { color: var(--gold); }
.po-copy em { font-style: normal; font-family: var(--font-mono); font-size: 6.5px; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.po-stats { display: flex; gap: 4px; margin-top: 2px; }
.po-stats i {
  font-style: normal; min-width: 22px; padding: 1px 3px;
  border: 1px solid #333b45; font-family: var(--font-mono); font-size: 6.5px; color: var(--muted);
  text-align: center;
}
.prep-tip { display: flex; align-items: flex-start; gap: 7px; padding: 8px 0; font-family: var(--font-mono); font-size: 7px; line-height: 1.55; color: var(--dim); }
