.result-sub { color: var(--muted); font-size: 11.5px; line-height: 1.55; max-width: 480px; }
.result-rows { display: grid; margin-top: 14px; border-top: 1px solid rgba(255, 255, 255, .06); }
.result-line { display: flex; justify-content: space-between; gap: 10px; padding: 7px 0; border-bottom: 1px solid rgba(255, 255, 255, .045); font-family: var(--font-mono); font-size: 8px; color: var(--dim); }
.result-line strong { color: var(--muted); font-size: 9px; }
.result-line.is-good strong { color: var(--green); }
.result-line.is-bad strong { color: #ff8b8b; }
.result-line.is-hot strong { color: #ff9d7a; }
.result-line.is-gold strong { color: var(--gold); }
.captured-block {
  display: grid; grid-template-columns: 72px 1fr auto; align-items: center; gap: 10px;
  margin-top: 12px; padding: 10px;
  border: 1px solid color-mix(in srgb, var(--tc) 30%, var(--line));
