.result-card.is-victory { grid-template-columns: 240px 1fr; background: radial-gradient(circle at 18% 45%, rgba(240, 199, 94, .1), transparent 45%), #0d1015; }
.result-card.is-victory .result-main h2 { color: var(--gold-2); text-shadow: 0 0 32px rgba(240, 199, 94, .25); }
